# Code generated by Claude
# Makes a new reference baseline for ONE bench scenario (manual, teleop or policy) from a clean copy of a commit.
# usage: bash experiments/cc_bench_regen.sh [--dry-run] [--commit REV] <manual|teleop|policy>
#   --dry-run     print what would be done; run nothing and write nothing
#   --commit REV  the commit to build from (default HEAD). A clean worktree of it is made outside the repo,
#                 so uncommitted edits cannot leak into the run.
# Steps, in order (each one stops the script if it fails, and then nothing is written into the repo):
#   1. make a worktree of REV in a temporary folder (outside the repo); link in the venv and the robot mesh folder
#   2. run the scenario twice there, through run_capped.sh (6 GB memory cap), one run at a time under the MuJoCo lock
#   3. if the two runs are not byte-identical: stop, write nothing (the outputs are kept under /tmp for a look)
#   4. write experiments/baselines/<scenario>_reference_<YYYYMMDD>_<shorthash>.csv (refuses to overwrite an existing file)
#      and a README note beside it (commit, date, command, settings, rows and columns, SHA-256, run match)
#   5. move the old CURRENT file to experiments/baselines/retired/ with git mv, and update INDEX.csv
#      (old row RETIRED, new row CURRENT; a NO_CURRENT row for the scenario is replaced)
#   6. remove the worktree
# Nothing is committed. Review with git status and git diff --stat, then commit by explicit path.
set -u
cd "$(dirname "$0")/.."
PY=.venv/bin/python
DRY=0; REV=HEAD; SC=""
while [ $# -gt 0 ]; do
  case "$1" in
    --dry-run) DRY=1 ;;
    --commit) shift; REV="${1:-}" ;;
    manual|teleop|policy) SC="$1" ;;
    -h|--help) sed -n '2,20p' "$0"; exit 0 ;;
    *) echo "cc_bench_regen: unknown argument '$1'" >&2; exit 2 ;;
  esac
  shift
done
[ -n "$SC" ] || { echo "cc_bench_regen: name one scenario: manual, teleop or policy" >&2; exit 2; }
FULL=$(git rev-parse --verify --quiet "$REV^{commit}") || { echo "cc_bench_regen: '$REV' is not a commit" >&2; exit 2; }
SHORT=$(git rev-parse --short=7 "$FULL")
DATE=$(date +%Y%m%d)
ISO=$(date +%Y-%m-%d)
NAME="${SC}_reference_${DATE}_${SHORT}"
CSV="experiments/baselines/$NAME.csv"
README="experiments/baselines/$NAME.README.txt"

# The CURRENT file now (empty if the scenario is NO_CURRENT). Exit 2, 4 (no index, no row) stops the script: never guess.
OLD=$($PY experiments/cc_bench_index.py current "$SC" 2>/dev/null); RC=$?
case $RC in
  0) ;;
  3) OLD="" ;;
  *) echo "cc_bench_regen: cannot read experiments/baselines/INDEX.csv for '$SC' (exit $RC); stopping" >&2; exit 1 ;;
esac
for f in "$CSV" "$README"; do
  [ -e "$f" ] && { echo "cc_bench_regen: $f already exists; not overwriting. Use another commit or remove it by hand." >&2; exit 1; }
done

if [ "$DRY" = 1 ]; then
  echo "DRY RUN: nothing is run or written."
  echo "  scenario:        $SC"
  echo "  commit:          $FULL ($SHORT)"
  echo "  would create:    $CSV"
  echo "                   $README"
  if [ -n "$OLD" ]; then echo "  would retire:    experiments/baselines/$OLD (git mv to experiments/baselines/retired/, row RETIRED)"; else echo "  would retire:    nothing (the scenario is NO_CURRENT)"; fi
  echo "  would update:    experiments/baselines/INDEX.csv (new CURRENT row for $NAME.csv)"
  echo "  would do:        worktree of $SHORT in a temporary folder; link .venv and deps/OpenArm-Combined; run '$SC' twice via run_capped.sh under data/locks/mujoco.lock;"
  echo "                   stop if the runs differ; remove the worktree. Nothing is committed."
  exit 0
fi

# Step 1: a clean worktree of the commit, outside the repo.
[ -d deps/OpenArm-Combined ] && [ -n "$(ls -A deps/OpenArm-Combined)" ] || { echo "cc_bench_regen: deps/OpenArm-Combined (robot meshes) is empty; stopping" >&2; exit 1; }
WT=$(mktemp -d /tmp/cc_regen_wt.XXXXXX)
OUT=$(mktemp -d /tmp/cc_regen_out.XXXXXX)
cleanup() {
  if [ -d "$WT" ]; then
    [ -L "$WT/.venv" ] && rm "$WT/.venv"
    [ -L "$WT/deps/OpenArm-Combined" ] && rm "$WT/deps/OpenArm-Combined"
    git worktree remove --force "$WT" >/dev/null 2>&1 || echo "cc_bench_regen: could not remove worktree $WT; remove it by hand (git worktree remove)" >&2
  fi
}
trap cleanup EXIT
git worktree add --detach "$WT" "$FULL" >/dev/null 2>&1 || { echo "cc_bench_regen: could not make a worktree of $SHORT; stopping" >&2; exit 1; }
ln -s "$PWD/.venv" "$WT/.venv" || { echo "cc_bench_regen: could not link .venv; stopping" >&2; exit 1; }
rmdir "$WT/deps/OpenArm-Combined" && ln -s "$PWD/deps/OpenArm-Combined" "$WT/deps/OpenArm-Combined" || { echo "cc_bench_regen: could not link the mesh folder; stopping" >&2; exit 1; }

# Step 2: two runs, one at a time, through run_capped.sh (its cd is the worktree root).
mkdir -p data/locks
LOCK="$PWD/data/locks/mujoco.lock"
for i in 1 2; do
  LOG="$OUT/run$i.log"; CSVR="$OUT/run$i.csv"
  flock "$LOCK" bash "$WT/experiments/run_capped.sh" "$LOG" env CC_HEADLESS=1 bash experiments/cc_bench_scenarios.sh "$SC" "$CSVR"
  grep -q "=== exit 0" "$LOG" && [ -s "$CSVR" ] || { echo "cc_bench_regen: run $i failed (log $LOG); nothing written" >&2; exit 1; }
done

# Step 3: the two runs must match byte for byte.
cmp -s "$OUT/run1.csv" "$OUT/run2.csv" || { echo "cc_bench_regen: the two runs DIFFER; nothing written (outputs in $OUT)" >&2; exit 1; }

# Step 4: the new file and its note (written to a temporary name, then renamed).
ROWS=$(wc -l < "$OUT/run1.csv"); COLS=$(head -1 "$OUT/run1.csv" | awk -F, '{print NF}')
SHA=$(sha256sum "$OUT/run1.csv" | cut -d' ' -f1)
cp "$OUT/run1.csv" "$CSV.tmp" && mv "$CSV.tmp" "$CSV"
{
  echo "Bench scenario baseline: $SC ($NAME.csv)"
  echo "================================================"
  echo "Made from commit: $FULL ($SHORT), from a clean worktree (uncommitted edits cannot leak in)"
  echo "Date: $ISO"
  echo "Command: bash experiments/cc_bench_regen.sh $SC (inside it: bash experiments/run_capped.sh <log> env CC_HEADLESS=1 bash experiments/cc_bench_scenarios.sh $SC <csv>)"
  echo "Settings (copied from experiments/cc_bench_scenarios.sh at $SHORT, case '$SC'):"
  awk -v s="$SC" '$0 ~ "^ " s "\\)" {p=1; print; next} p && /^ [a-z]+\)/ {p=0} p' "$WT/experiments/cc_bench_scenarios.sh"
  echo "Runs: 2 (byte-identical: yes)"
  echo "Size: $ROWS lines (one header and $((ROWS - 1)) data rows), $COLS columns"
  echo "SHA-256: $SHA"
} > "$README.tmp" && mv "$README.tmp" "$README"

# Step 5: the old CURRENT file goes to retired/ (git mv, staged, not committed); then INDEX.csv is updated.
if [ -n "$OLD" ]; then
  mkdir -p experiments/baselines/retired
  git mv "experiments/baselines/$OLD" "experiments/baselines/retired/$(basename "$OLD")" || { echo "cc_bench_regen: git mv of $OLD failed; the new files are written, INDEX.csv is NOT updated (fix by hand)" >&2; exit 1; }
fi
$PY experiments/cc_bench_index.py promote "$SC" "$NAME.csv" "$ISO" "$SHORT" "$SHA" yes "made from clean commit $SHORT by cc_bench_regen.sh" \
  || { echo "cc_bench_regen: INDEX.csv update failed; the new files are written (fix INDEX.csv by hand)" >&2; exit 1; }

echo "=== $SC: the two runs are byte-identical ($ROWS lines, $COLS columns); wrote $CSV and $README"
[ -n "$OLD" ] && echo "=== retired: experiments/baselines/$OLD -> retired/ (git mv, staged)"
echo "=== INDEX.csv updated. Nothing committed. Review with git status, then commit by explicit path."
